INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-01', 'The School Day', 'This lesson covers school subjects studied in school and daily activities related to the school day routine.', '{"details":[{"word":"art","meaning":"a school subject involving drawing, painting, and creative activities","burmese":""},{"word":"biology","meaning":"a school subject studying living organisms and life","burmese":""},{"word":"chemistry","meaning":"a school subject studying substances and their reactions","burmese":""},{"word":"English","meaning":"the school subject of studying the English language","burmese":""},{"word":"French","meaning":"the school subject of studying the French language","burmese":""},{"word":"geography","meaning":"a school subject studying the earth, countries, and landscapes","burmese":""},{"word":"German","meaning":"the school subject of studying the German language","burmese":""},{"word":"history","meaning":"a school subject studying past events","burmese":""},{"word":"ICT","meaning":"Information and Communication Technology; a school subject about computers and technology","burmese":""},{"word":"maths","meaning":"the school subject of studying numbers, shapes, and calculations","burmese":""},{"word":"music","meaning":"a school subject involving singing, playing instruments, and learning about music","burmese":""},{"word":"PE","meaning":"Physical Education; a school subject involving sports and exercise","burmese":""},{"word":"physics","meaning":"a school subject studying energy, matter, and the laws of nature","burmese":""},{"word":"Spanish","meaning":"the school subject of studying the Spanish language","burmese":""},{"word":"go to school","meaning":"to travel to school to attend classes","burmese":""},{"word":"have lunch","meaning":"to eat a midday meal","burmese":""},{"word":"have a break","meaning":"to rest for a short time during the school day","burmese":""},{"word":"get up","meaning":"to get out of bed in the morning","burmese":""},{"word":"do homework","meaning":"to complete school assignments at home","burmese":""},{"word":"go to bed","meaning":"to go to sleep for the night","burmese":""},{"word":"start school","meaning":"to begin attending classes for the day","burmese":""},{"word":"get dressed","meaning":"to put on clothes","burmese":""},{"word":"have dinner","meaning":"to eat the main evening meal","burmese":""},{"word":"finish school","meaning":"to complete the school day and leave school","burmese":""},{"word":"have breakfast","meaning":"to eat the first meal of the day in the morning","burmese":""},{"word":"go home","meaning":"to travel back to one''s house","burmese":""}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-02', 'Free-time Activities', 'This lesson covers common hobbies and activities that people do in their free time.', '{"details":[{"word":"chat online","meaning":"to talk to people using the internet","burmese":""},{"word":"dance","meaning":"to move rhythmically to music","burmese":""},{"word":"do sport","meaning":"to participate in physical games or exercises","burmese":""},{"word":"draw","meaning":"to make pictures using a pen or pencil","burmese":""},{"word":"go shopping","meaning":"to visit shops to buy things","burmese":""},{"word":"go out with friends","meaning":"to leave home and spend time with friends","burmese":""},{"word":"listen to music","meaning":"to hear and enjoy music","burmese":""},{"word":"play the guitar","meaning":"to make music using a guitar","burmese":""},{"word":"play the piano","meaning":"to make music using a piano","burmese":""},{"word":"read","meaning":"to look at and understand written words","burmese":""},{"word":"surf the Internet","meaning":"to look at different websites on the internet","burmese":""},{"word":"take photos","meaning":"to use a camera to capture images","burmese":""},{"word":"watch films","meaning":"to view movies for entertainment","burmese":""}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-03', 'Places to Go in a Town', 'This lesson covers common public places and venues found in a town or city.', '{"details":[{"word":"cinema","meaning":"a place where films are shown on a big screen","burmese":""},{"word":"fast-food restaurant","meaning":"a restaurant that serves quick, prepared meals","burmese":""},{"word":"library","meaning":"a building where books are kept and can be borrowed","burmese":""},{"word":"museum","meaning":"a building where historical or artistic objects are displayed","burmese":""},{"word":"park","meaning":"an open area of land with grass and trees for public use","burmese":""},{"word":"shopping centre","meaning":"a large building with many different shops","burmese":""},{"word":"sports centre","meaning":"a building with facilities for different sports and activities","burmese":""},{"word":"stadium","meaning":"a large outdoor venue with seats for watching sports or concerts","burmese":""},{"word":"swimming pool","meaning":"a container filled with water for swimming","burmese":""},{"word":"theatre","meaning":"a building where plays and performances are shown","burmese":""}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049003-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-04', 'Rooms', 'This lesson covers the different rooms found in a house or flat.', '{"details":[{"word":"bathroom","meaning":"a room with a bath, shower, and toilet","burmese":""},{"word":"bedroom","meaning":"a room where you sleep","burmese":""},{"word":"dining room","meaning":"a room where people eat meals at a table","burmese":""},{"word":"garage","meaning":"a building for keeping a car, or a place where cars are repaired","burmese":""},{"word":"garden","meaning":"a piece of land next to a house with plants and grass","burmese":""},{"word":"hall","meaning":"the area just inside the front door of a house","burmese":""},{"word":"kitchen","meaning":"a room where food is prepared and cooked","burmese":""},{"word":"living room","meaning":"a room for relaxing and watching TV","burmese":""}]}'::jsonb, 4) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049004-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-05', 'Household Objects and Furniture', 'This lesson covers common items, furniture, and appliances found in a home.', '{"details":[{"word":"armchair","meaning":"a comfortable chair with sides for your arms","burmese":""},{"word":"bath","meaning":"a large container for holding water to wash your body","burmese":""},{"word":"bed","meaning":"a piece of furniture for sleeping on","burmese":""},{"word":"CD player","meaning":"a device for playing music CDs","burmese":""},{"word":"chair","meaning":"a piece of furniture for sitting on","burmese":""},{"word":"clock","meaning":"a device that shows the time","burmese":""},{"word":"computer","meaning":"an electronic device for processing data","burmese":""},{"word":"cooker","meaning":"an appliance used for cooking food","burmese":""},{"word":"cupboard","meaning":"a piece of furniture with shelves and a door for storing things","burmese":""},{"word":"desk","meaning":"a piece of furniture with a flat surface for working","burmese":""},{"word":"dishwasher","meaning":"a machine that washes dirty dishes automatically","burmese":""},{"word":"DVD player","meaning":"a device for playing DVDs and watching films","burmese":""},{"word":"fridge","meaning":"an appliance for keeping food and drinks cold","burmese":""},{"word":"games console","meaning":"an electronic device for playing video games","burmese":""},{"word":"lamp","meaning":"a device that gives light, usually on a table or floor","burmese":""},{"word":"light","meaning":"something that produces brightness so you can see","burmese":""},{"word":"microwave","meaning":"an appliance for heating and cooking food quickly","burmese":""},{"word":"mirror","meaning":"a piece of glass that reflects your image","burmese":""},{"word":"phone","meaning":"a device for making calls and sending messages","burmese":""},{"word":"painting","meaning":"a picture made using paint","burmese":""},{"word":"poster","meaning":"a large printed picture or notice for a wall","burmese":""},{"word":"radiator","meaning":"a device for heating a room","burmese":""},{"word":"shelf","meaning":"a flat horizontal surface attached to a wall for holding things","burmese":""},{"word":"shelves","meaning":"plural of shelf; multiple flat surfaces for holding things","burmese":""},{"word":"shower","meaning":"a device for spraying water to wash your body","burmese":""},{"word":"sink","meaning":"a bowl with a tap for washing dishes or hands","burmese":""},{"word":"sofa","meaning":"a long soft seat for several people","burmese":""},{"word":"table","meaning":"a piece of furniture with a flat top and legs","burmese":""},{"word":"toilet","meaning":"a bowl for getting rid of body waste","burmese":""},{"word":"TV","meaning":"a device for receiving and watching television programmes","burmese":""},{"word":"washing machine","meaning":"a machine that washes clothes automatically","burmese":""},{"word":"window","meaning":"an opening in a wall with glass to let in light and air","burmese":""}]}'::jsonb, 5) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049005-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-06', 'Jobs Around the House', 'This lesson covers common household chores and tasks done at home.', '{"details":[{"word":"cook","meaning":"to prepare and heat food","burmese":""},{"word":"do the ironing","meaning":"to use an iron to remove creases from clothes","burmese":""},{"word":"do the shopping","meaning":"to buy food and household items from shops","burmese":""},{"word":"do the washing","meaning":"to wash clothes and other fabrics","burmese":""},{"word":"lay the table","meaning":"to put plates, cutlery, and glasses on the table before a meal","burmese":""},{"word":"make the bed","meaning":"to arrange sheets and blankets neatly on a bed","burmese":""},{"word":"take the rubbish out","meaning":"to remove waste to an outside bin","burmese":""},{"word":"tidy up","meaning":"to put things back in their proper places to make a room neat","burmese":""},{"word":"wash the dishes","meaning":"to clean plates, cups, and cutlery after a meal","burmese":""}]}'::jsonb, 6) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049006-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-07', 'Parts of the Body', 'This lesson covers the main parts of the human body.', '{"details":[{"word":"ankle","meaning":"the joint connecting the foot to the leg","burmese":""},{"word":"arm","meaning":"the limb extending from the shoulder to the hand","burmese":""},{"word":"back","meaning":"the rear part of the human body","burmese":""},{"word":"chest","meaning":"the front part of the body between the neck and the stomach","burmese":""},{"word":"ear","meaning":"the body part on the side of the head used for hearing","burmese":""},{"word":"elbow","meaning":"the joint in the middle of the arm","burmese":""},{"word":"face","meaning":"the front part of the head with eyes, nose, and mouth","burmese":""},{"word":"finger","meaning":"one of the five parts at the end of the hand","burmese":""},{"word":"foot","meaning":"the part of the body you stand on; plural: feet","burmese":""},{"word":"hand","meaning":"the part of the body at the end of the arm with fingers","burmese":""},{"word":"head","meaning":"the top part of the body containing the brain and eyes","burmese":""},{"word":"knee","meaning":"the joint in the middle of the leg","burmese":""},{"word":"leg","meaning":"the limb used for walking and standing","burmese":""},{"word":"mouth","meaning":"the opening in the face used for eating and speaking","burmese":""},{"word":"neck","meaning":"the part connecting the head to the body","burmese":""},{"word":"nose","meaning":"the part of the face used for smelling and breathing","burmese":""},{"word":"shoulder","meaning":"the part of the body at the top of the arm","burmese":""},{"word":"stomach","meaning":"the front part of the body between the chest and legs","burmese":""},{"word":"toe","meaning":"one of the five parts at the end of the foot","burmese":""},{"word":"wrist","meaning":"the joint connecting the hand to the arm","burmese":""}]}'::jsonb, 7) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049007-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-08', 'Physical Activities', 'This lesson covers verbs describing actions involving physical movement and activity.', '{"details":[{"word":"climb","meaning":"to go up or over something using hands and feet","burmese":""},{"word":"dive","meaning":"to jump into water headfirst","burmese":""},{"word":"fall","meaning":"to move downwards quickly, usually by accident","burmese":""},{"word":"hit","meaning":"to bring your hand or an object against something with force","burmese":""},{"word":"jump","meaning":"to push yourself off the ground into the air","burmese":""},{"word":"kick","meaning":"to hit something with your foot","burmese":""},{"word":"rest","meaning":"to stop doing something in order to relax or recover","burmese":""},{"word":"ride","meaning":"to sit on and control a horse or bike","burmese":""},{"word":"run","meaning":"to move quickly on foot","burmese":""},{"word":"skate","meaning":"to move on ice or a surface using skates","burmese":""},{"word":"ski","meaning":"to move over snow on skis","burmese":""},{"word":"swim","meaning":"to move through water using your body","burmese":""}]}'::jsonb, 8) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
