INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049010-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-11', 'Words Connected with Tourism', 'This lesson covers vocabulary related to travel and tourism.', '{"details":[{"word":"book","meaning":"to reserve or arrange to stay at a hotel or travel on transport (verb)","burmese":""},{"word":"guidebook","meaning":"a book with information for tourists about a place","burmese":""},{"word":"luggage","meaning":"suitcases and bags taken when travelling","burmese":""},{"word":"package holiday","meaning":"a holiday where flights, hotel, and meals are all included","burmese":""},{"word":"passport","meaning":"an official document for travelling to other countries","burmese":""},{"word":"sightseeing","meaning":"visiting famous places as a tourist","burmese":""},{"word":"souvenir","meaning":"an object bought to remember a place or holiday","burmese":""},{"word":"tickets","meaning":"pieces of paper or cards that allow you to travel or enter a place","burmese":""},{"word":"travel agency","meaning":"a company that organises holidays and travel","burmese":""},{"word":"trip","meaning":"a short journey to a place and back again","burmese":""},{"word":"excursion","meaning":"a short trip or visit to a place of interest","burmese":""}]}'::jsonb, 11) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049011-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-12', 'Transport', 'This lesson covers different types of vehicles and means of transport.', '{"details":[{"word":"bike","meaning":"a two-wheeled vehicle you pedal","burmese":""},{"word":"boat","meaning":"a vehicle that travels on water","burmese":""},{"word":"bus","meaning":"a large vehicle that carries many passengers on roads","burmese":""},{"word":"car","meaning":"a road vehicle with an engine, usually for a small number of people","burmese":""},{"word":"coach","meaning":"a large bus for long-distance travel","burmese":""},{"word":"helicopter","meaning":"an aircraft that can fly up and down and hover","burmese":""},{"word":"lorry","meaning":"a large vehicle for transporting goods on roads","burmese":""},{"word":"moped","meaning":"a small motorcycle with pedals","burmese":""},{"word":"motorbike","meaning":"a two-wheeled vehicle with an engine","burmese":""},{"word":"plane","meaning":"an aircraft with wings and an engine for flying","burmese":""},{"word":"ship","meaning":"a large boat for travelling on the sea","burmese":""},{"word":"taxi","meaning":"a car you pay to travel in","burmese":""},{"word":"train","meaning":"a series of connected carriages that travel on rails","burmese":""},{"word":"tram","meaning":"a vehicle that runs on rails through a city","burmese":""},{"word":"underground","meaning":"a train system that runs below the ground","burmese":""},{"word":"van","meaning":"a vehicle for carrying goods","burmese":""}]}'::jsonb, 12) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
