INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049013-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-14', 'Jobs and Work', 'This lesson covers common job titles and occupations.', '{"details":[{"word":"actor","meaning":"a man who performs in plays or films","burmese":""},{"word":"actress","meaning":"a woman who performs in plays or films","burmese":""},{"word":"artist","meaning":"a person who creates paintings or other art","burmese":""},{"word":"builder","meaning":"a person who builds and repairs buildings","burmese":""},{"word":"bus driver","meaning":"a person who drives a bus","burmese":""},{"word":"taxi driver","meaning":"a person who drives a taxi","burmese":""},{"word":"lorry driver","meaning":"a person who drives a lorry","burmese":""},{"word":"businessman","meaning":"a man who works in business","burmese":""},{"word":"businesswoman","meaning":"a woman who works in business","burmese":""},{"word":"cleaner","meaning":"a person whose job is to clean buildings","burmese":""},{"word":"cook","meaning":"a person who prepares and cooks food","burmese":""},{"word":"dentist","meaning":"a person who treats problems with teeth","burmese":""},{"word":"doctor","meaning":"a person who treats sick or injured people","burmese":""},{"word":"engineer","meaning":"a person who designs, builds, or repairs machines and structures","burmese":""},{"word":"farmer","meaning":"a person who owns or works on a farm","burmese":""},{"word":"footballer","meaning":"a person who plays football","burmese":""},{"word":"hairdresser","meaning":"a person who cuts and styles hair","burmese":""},{"word":"journalist","meaning":"a person who writes for newspapers or reports news","burmese":""},{"word":"mechanic","meaning":"a person who repairs machines, especially car engines","burmese":""},{"word":"nurse","meaning":"a person who cares for sick or injured people in hospital","burmese":""},{"word":"secretary","meaning":"a person who does office work such as typing and answering phones","burmese":""},{"word":"shop assistant","meaning":"a person who serves customers in a shop","burmese":""},{"word":"singer","meaning":"a person who sings","burmese":""},{"word":"teacher","meaning":"a person who teaches in a school","burmese":""},{"word":"professor","meaning":"a senior teacher at a university","burmese":""},{"word":"waiter","meaning":"a man who serves food and drinks in a restaurant","burmese":""},{"word":"waitress","meaning":"a woman who serves food and drinks in a restaurant","burmese":""},{"word":"writer","meaning":"a person who writes books, stories, or articles","burmese":""},{"word":"author","meaning":"a person who writes a book","burmese":""}]}'::jsonb, 14) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049014-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-15', 'Culture and Work', 'This lesson covers vocabulary related to the arts, culture, and creative professions.', '{"details":[{"word":"art","meaning":"the expression of creative skill and imagination","burmese":""},{"word":"ballet","meaning":"a form of dance performed to music","burmese":""},{"word":"classical music","meaning":"a style of music that follows traditional forms","burmese":""},{"word":"composer","meaning":"a person who writes music","burmese":""},{"word":"dancer","meaning":"a person who dances","burmese":""},{"word":"director","meaning":"a person who controls a film or theatre production","burmese":""},{"word":"film","meaning":"a movie; a story shown in moving pictures","burmese":""},{"word":"literature","meaning":"written works regarded as having artistic merit","burmese":""},{"word":"musician","meaning":"a person who plays or composes music","burmese":""},{"word":"novelist","meaning":"a person who writes novels","burmese":""},{"word":"opera","meaning":"a dramatic work set to music","burmese":""},{"word":"painter","meaning":"a person who paints pictures","burmese":""},{"word":"playwright","meaning":"a person who writes plays","burmese":""},{"word":"poet","meaning":"a person who writes poetry","burmese":""},{"word":"poetry","meaning":"literary work in which meaning is expressed through rhythm and sound","burmese":""},{"word":"singer","meaning":"a person who sings","burmese":""},{"word":"theatre","meaning":"a building or place where plays are performed","burmese":""}]}'::jsonb, 15) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049015-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-16', 'Containers', 'This lesson covers words for containers and the measure words used with food and drink.', '{"details":[{"word":"bottle","meaning":"a container with a narrow neck for liquids, e.g. a bottle of water","burmese":""},{"word":"can","meaning":"a metal container for drinks, e.g. a can of fizzy drink","burmese":""},{"word":"carton","meaning":"a cardboard container for drinks, e.g. a carton of orange juice","burmese":""},{"word":"cup","meaning":"a small container for drinking, e.g. a cup of coffee","burmese":""},{"word":"glass","meaning":"a container made of glass for drinking, e.g. a glass of milk","burmese":""},{"word":"packet","meaning":"a small bag or container for food, e.g. a packet of biscuits","burmese":""},{"word":"slice","meaning":"a thin, flat piece of food, e.g. a slice of pizza","burmese":""}]}'::jsonb, 16) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049016-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-17', 'Wild Animals and Insects', 'This lesson covers the names of wild animals and insects.', '{"details":[{"word":"alligator","meaning":"a large reptile with a long mouth and teeth","burmese":""},{"word":"bear","meaning":"a large, heavy mammal with thick fur","burmese":""},{"word":"bee","meaning":"a flying insect that makes honey","burmese":""},{"word":"eagle","meaning":"a large bird of prey with a sharp beak","burmese":""},{"word":"jellyfish","meaning":"a sea creature with a soft body and tentacles","burmese":""},{"word":"lizard","meaning":"a small reptile with a long body and tail","burmese":""},{"word":"scorpion","meaning":"an arachnid with a curved tail that stings","burmese":""},{"word":"shark","meaning":"a large fish that lives in the sea","burmese":""},{"word":"snake","meaning":"a long, thin reptile with no legs","burmese":""},{"word":"spider","meaning":"a small creature with eight legs that spins webs","burmese":""},{"word":"tiger","meaning":"a large wild cat with orange and black stripes","burmese":""},{"word":"wolf","meaning":"a wild animal similar to a dog that hunts in groups","burmese":""}]}'::jsonb, 17) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049017-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-18', 'The Natural World', 'This lesson covers vocabulary for natural features and landscapes.', '{"details":[{"word":"field","meaning":"an open area of land, often for growing crops or keeping animals","burmese":""},{"word":"flowers","meaning":"the colourful parts of plants","burmese":""},{"word":"forest","meaning":"a large area covered with trees","burmese":""},{"word":"grass","meaning":"a common green plant covering the ground","burmese":""},{"word":"hill","meaning":"a raised area of land, smaller than a mountain","burmese":""},{"word":"island","meaning":"a piece of land surrounded by water","burmese":""},{"word":"lake","meaning":"a large area of water surrounded by land","burmese":""},{"word":"mountain","meaning":"a very high natural area of land","burmese":""},{"word":"river","meaning":"a large natural stream of water flowing to the sea","burmese":""},{"word":"sky","meaning":"the area above the earth where you can see clouds and the sun","burmese":""},{"word":"valley","meaning":"a low area of land between hills or mountains","burmese":""},{"word":"waterfall","meaning":"water falling from a height in a river or stream","burmese":""}]}'::jsonb, 18) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049018-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-19', 'The Weather', 'This lesson covers words for describing weather conditions and the sky.', '{"details":[{"word":"cloud","meaning":"a white or grey mass in the sky","burmese":""},{"word":"cloudy","meaning":"the sky is covered with clouds","burmese":""},{"word":"cold","meaning":"a low temperature; not warm","burmese":""},{"word":"dry","meaning":"not wet or rainy","burmese":""},{"word":"fog","meaning":"thick cloud near the ground that makes it hard to see","burmese":""},{"word":"foggy","meaning":"covered with fog","burmese":""},{"word":"hot","meaning":"a high temperature; very warm","burmese":""},{"word":"ice","meaning":"frozen water","burmese":""},{"word":"icy","meaning":"covered with ice; very cold","burmese":""},{"word":"rain","meaning":"water falling from clouds in drops","burmese":""},{"word":"rainy","meaning":"having a lot of rain","burmese":""},{"word":"snow","meaning":"soft white pieces of frozen water falling from the sky","burmese":""},{"word":"snowy","meaning":"covered with snow","burmese":""},{"word":"storm","meaning":"very bad weather with strong wind and rain","burmese":""},{"word":"stormy","meaning":"having a lot of storms","burmese":""},{"word":"sun","meaning":"the bright star that gives light and heat during the day","burmese":""},{"word":"sunny","meaning":"bright with sunshine","burmese":""},{"word":"warm","meaning":"fairly hot; more comfortable than hot","burmese":""},{"word":"wet","meaning":"covered with water or another liquid","burmese":""},{"word":"wind","meaning":"air moving naturally outside","burmese":""},{"word":"windy","meaning":"having a lot of wind","burmese":""}]}'::jsonb, 19) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049019-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-20', 'Feelings', 'This lesson covers adjectives that describe emotions and how people feel.', '{"details":[{"word":"angry","meaning":"feeling strong displeasure or annoyance","burmese":""},{"word":"bored","meaning":"feeling tired and impatient because something is not interesting","burmese":""},{"word":"confused","meaning":"unable to understand or think clearly","burmese":""},{"word":"disappointed","meaning":"feeling sad because something was not as good as expected","burmese":""},{"word":"excited","meaning":"feeling very happy and enthusiastic","burmese":""},{"word":"frightened","meaning":"feeling afraid or scared","burmese":""},{"word":"happy","meaning":"feeling pleasure and enjoyment","burmese":""},{"word":"interested","meaning":"wanting to learn or know more about something","burmese":""},{"word":"relaxed","meaning":"feeling calm and free from worry","burmese":""},{"word":"sad","meaning":"feeling unhappy or sorrowful","burmese":""},{"word":"stressed","meaning":"feeling very worried or under pressure","burmese":""},{"word":"surprised","meaning":"feeling amazement caused by something unexpected","burmese":""},{"word":"tired","meaning":"feeling in need of sleep or rest","burmese":""},{"word":"worried","meaning":"feeling anxious or troubled about something","burmese":""}]}'::jsonb, 20) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049020-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-21', 'Personality', 'This lesson covers adjectives that describe a person''s character and personality.', '{"details":[{"word":"cheerful","meaning":"happy and positive in attitude","burmese":""},{"word":"hard-working","meaning":"putting a lot of effort into work","burmese":""},{"word":"intelligent","meaning":"having a high level of intelligence and understanding","burmese":""},{"word":"kind","meaning":"generous, friendly, and considerate of others","burmese":""},{"word":"lazy","meaning":"unwilling to work or use energy","burmese":""},{"word":"quiet","meaning":"not making much noise; calm and reserved","burmese":""},{"word":"responsible","meaning":"able to be trusted to do things well","burmese":""},{"word":"serious","meaning":"thinking about things carefully; not joking","burmese":""}]}'::jsonb, 21) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049021-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-22', 'Social Problems', 'This lesson covers vocabulary for major issues affecting society and communities.', '{"details":[{"word":"crime","meaning":"illegal activities and actions","burmese":""},{"word":"homelessness","meaning":"the state of not having a home to live in","burmese":""},{"word":"hunger","meaning":"the feeling of needing food","burmese":""},{"word":"pollution","meaning":"the harmful damage caused to the environment by waste and chemicals","burmese":""},{"word":"poverty","meaning":"the state of being very poor","burmese":""},{"word":"unemployment","meaning":"the state of not having a paid job","burmese":""},{"word":"violence","meaning":"the use of physical force to hurt or damage people or things","burmese":""}]}'::jsonb, 22) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049022-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-23', 'Clothes', 'This lesson covers common types of clothing worn on the body.', '{"details":[{"word":"blouse","meaning":"a loose top for women","burmese":""},{"word":"boots","meaning":"strong shoes that cover the foot and ankle","burmese":""},{"word":"coat","meaning":"a thick outer garment worn for warmth","burmese":""},{"word":"dress","meaning":"a one-piece garment for women or girls","burmese":""},{"word":"jacket","meaning":"a short, light coat","burmese":""},{"word":"jeans","meaning":"trousers made of strong cotton fabric","burmese":""},{"word":"jumper","meaning":"a warm knitted top for the upper body","burmese":""},{"word":"sweater","meaning":"a warm knitted top for the upper body","burmese":""},{"word":"leggings","meaning":"tight-fitting trousers for women or girls","burmese":""},{"word":"shirt","meaning":"a formal top with a collar and buttons","burmese":""},{"word":"shoes","meaning":"coverings for the feet","burmese":""},{"word":"shorts","meaning":"trousers that end above the knees","burmese":""},{"word":"skirt","meaning":"a garment hanging from the waist for women or girls","burmese":""},{"word":"socks","meaning":"coverings for the feet worn inside shoes","burmese":""},{"word":"suit","meaning":"a set of matching clothes for formal wear","burmese":""},{"word":"sweatshirt","meaning":"a comfortable cotton top with long sleeves","burmese":""},{"word":"tie","meaning":"a long piece of cloth worn around the neck with a shirt","burmese":""},{"word":"tights","meaning":"close-fitting coverings for the legs and feet","burmese":""},{"word":"top","meaning":"a piece of clothing that covers the upper body","burmese":""},{"word":"tracksuit","meaning":"a set of loose clothing for sports or exercise","burmese":""},{"word":"trainers","meaning":"soft shoes worn for sports or casual wear","burmese":""},{"word":"trousers","meaning":"a garment covering the legs separately","burmese":""},{"word":"T-shirt","meaning":"a casual top with short sleeves and no buttons","burmese":""}]}'::jsonb, 23) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049023-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-24', 'Accessories', 'This lesson covers items that are worn with clothes to complete an outfit.', '{"details":[{"word":"belt","meaning":"a strip of leather or material worn around the waist","burmese":""},{"word":"cap","meaning":"a soft hat with a rounded top and a small peak at the front","burmese":""},{"word":"glasses","meaning":"frames with lenses worn in front of the eyes to help you see","burmese":""},{"word":"hat","meaning":"a covering for the head","burmese":""},{"word":"jewellery","meaning":"decorative items worn on the body such as rings and necklaces","burmese":""},{"word":"scarf","meaning":"a piece of material worn around the neck for warmth","burmese":""},{"word":"sunglasses","meaning":"dark glasses worn to protect the eyes from sunlight","burmese":""},{"word":"watch","meaning":"a small device worn on the wrist to tell the time","burmese":""}]}'::jsonb, 24) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049024-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-25', 'Shops', 'This lesson covers the names of different types of shops and stores.', '{"details":[{"word":"bakery","meaning":"a shop that sells bread and cakes","burmese":""},{"word":"bank","meaning":"a place where people keep and borrow money","burmese":""},{"word":"bookshop","meaning":"a shop that sells books","burmese":""},{"word":"butcher''s","meaning":"a shop that sells meat","burmese":""},{"word":"chemist''s","meaning":"a shop that sells medicine and health products","burmese":""},{"word":"clothes shop","meaning":"a shop that sells clothing","burmese":""},{"word":"department store","meaning":"a large shop with many different sections","burmese":""},{"word":"electrical goods shop","meaning":"a shop that sells electrical items such as TVs and computers","burmese":""},{"word":"greengrocer''s","meaning":"a shop that sells fruit and vegetables","burmese":""},{"word":"jeweller''s","meaning":"a shop that sells jewellery","burmese":""},{"word":"newsagent''s","meaning":"a shop that sells newspapers and magazines","burmese":""},{"word":"post office","meaning":"a place for sending letters and parcels","burmese":""},{"word":"shoe shop","meaning":"a shop that sells shoes","burmese":""},{"word":"sports shop","meaning":"a shop that sells sports equipment and clothing","burmese":""},{"word":"stationery shop","meaning":"a shop that sells paper, pens, and office supplies","burmese":""},{"word":"supermarket","meaning":"a large shop that sells food and household items","burmese":""}]}'::jsonb, 25) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049025-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-26', 'Ages and Stages of Life', 'This lesson covers vocabulary for the different stages of a person''s life and their age ranges.', '{"details":[{"word":"adolescence","meaning":"the period between childhood and adulthood","burmese":""},{"word":"baby","meaning":"a very young child, aged 0 to 3","burmese":""},{"word":"birth","meaning":"the time when a baby is born","burmese":""},{"word":"child","meaning":"a young person, aged 4 to 12","burmese":""},{"word":"childhood","meaning":"the period of being a child","burmese":""},{"word":"death","meaning":"the end of life","burmese":""},{"word":"middle age","meaning":"the period of life between about 35 and 64","burmese":""},{"word":"middle-aged","meaning":"in the period of life between about 35 and 64","burmese":""},{"word":"old age","meaning":"the later part of life","burmese":""},{"word":"senior citizen","meaning":"an older person, usually aged 65 or over","burmese":""},{"word":"teenager","meaning":"a young person aged 13 to 19","burmese":""},{"word":"young adult","meaning":"a person in the stage between adolescence and middle age, aged 20 to 34","burmese":""}]}'::jsonb, 26) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049026-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-27', 'The Family', 'This lesson covers vocabulary for family members and relationships.', '{"details":[{"word":"aunt","meaning":"the sister of your father or mother","burmese":""},{"word":"born","meaning":"to come into life as a baby","burmese":""},{"word":"brother","meaning":"a boy or man who has the same parents as you","burmese":""},{"word":"brother-in-law","meaning":"the brother of your husband or wife","burmese":""},{"word":"sister-in-law","meaning":"the sister of your husband or wife","burmese":""},{"word":"father-in-law","meaning":"the father of your husband or wife","burmese":""},{"word":"mother-in-law","meaning":"the mother of your husband or wife","burmese":""},{"word":"cousin","meaning":"the child of your aunt or uncle","burmese":""},{"word":"daughter","meaning":"a female child in relation to parents","burmese":""},{"word":"divorced","meaning":"having ended a marriage officially","burmese":""},{"word":"grandfather","meaning":"the father of your mother or father","burmese":""},{"word":"grandmother","meaning":"the mother of your mother or father","burmese":""},{"word":"grandson","meaning":"the son of your son or daughter","burmese":""},{"word":"granddaughter","meaning":"the daughter of your son or daughter","burmese":""},{"word":"husband","meaning":"a married man","burmese":""},{"word":"nephew","meaning":"the son of your brother or sister","burmese":""},{"word":"niece","meaning":"the daughter of your brother or sister","burmese":""},{"word":"one-parent family","meaning":"a family with only one parent raising the children","burmese":""},{"word":"only child","meaning":"a child with no brothers or sisters","burmese":""},{"word":"partner","meaning":"a person you live with and have a relationship with","burmese":""},{"word":"single","meaning":"not married or not in a relationship","burmese":""},{"word":"sister","meaning":"a girl or woman who has the same parents as you","burmese":""},{"word":"son","meaning":"a male child in relation to parents","burmese":""},{"word":"stepfather","meaning":"the man who is married to your mother but is not your real father","burmese":""},{"word":"stepmother","meaning":"the woman who is married to your father but is not your real mother","burmese":""},{"word":"uncle","meaning":"the brother of your father or mother","burmese":""},{"word":"wife","meaning":"a married woman","burmese":""}]}'::jsonb, 27) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049027-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-28', 'Crimes and Criminals', 'This lesson covers vocabulary for illegal activities, the people who commit them, and related verbs and nouns.', '{"details":[{"word":"break into","meaning":"to enter a building illegally by force (verb)","burmese":""},{"word":"burglar","meaning":"a person who breaks into buildings to steal (noun, person)","burmese":""},{"word":"burglary","meaning":"the crime of breaking into a building and stealing (noun)","burmese":""},{"word":"burgle","meaning":"to steal from a building after breaking in (verb)","burmese":""},{"word":"copy","meaning":"to make an illegal imitation of something (verb)","burmese":""},{"word":"damage","meaning":"to harm or break something (verb)","burmese":""},{"word":"fraud","meaning":"the crime of cheating people to gain money (noun)","burmese":""},{"word":"fraudster","meaning":"a person who commits fraud (noun, person)","burmese":""},{"word":"mug","meaning":"to attack and rob someone in a public place (verb)","burmese":""},{"word":"mugger","meaning":"a person who robs someone in a public place (noun, person)","burmese":""},{"word":"mugging","meaning":"the crime of robbing someone in a public place (noun)","burmese":""},{"word":"piracy","meaning":"the illegal copying and selling of books, music, or software (noun)","burmese":""},{"word":"pirate","meaning":"a person who illegally copies and sells copyrighted material (noun, person)","burmese":""},{"word":"rob","meaning":"to steal money or property from a person or place by force (verb)","burmese":""},{"word":"robber","meaning":"a person who steals from a person or place by force (noun, person)","burmese":""},{"word":"robbery","meaning":"the crime of stealing from a person or place by force (noun)","burmese":""},{"word":"shoplift","meaning":"to steal goods from a shop (verb)","burmese":""},{"word":"shoplifter","meaning":"a person who steals goods from a shop (noun, person)","burmese":""},{"word":"shoplifting","meaning":"the crime of stealing goods from a shop (noun)","burmese":""},{"word":"steal","meaning":"to take something that belongs to someone else without permission (verb)","burmese":""},{"word":"theft","meaning":"the crime of stealing (noun)","burmese":""},{"word":"thief","meaning":"a person who steals (noun, person)","burmese":""},{"word":"vandal","meaning":"a person who deliberately damages or destroys property (noun, person)","burmese":""},{"word":"vandalise","meaning":"to deliberately damage or destroy property (verb)","burmese":""},{"word":"vandalism","meaning":"the crime of deliberately damaging property (noun)","burmese":""},{"word":"violence","meaning":"the use of physical force to hurt or damage (noun)","burmese":""}]}'::jsonb, 28) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049028-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-29', 'Countries, Nationalities and Languages', 'This lesson covers the names of countries, the adjectives for people from those countries, and the languages spoken in them.', '{"details":[{"word":"Argentina","meaning":"Country: Argentina","burmese":""},{"word":"Argentinian","meaning":"Nationality: Argentinian","burmese":""},{"word":"Spanish","meaning":"Language: Spanish","burmese":""},{"word":"Austria","meaning":"Country: Austria","burmese":""},{"word":"Austrian","meaning":"Nationality: Austrian","burmese":""},{"word":"German","meaning":"Language: German","burmese":""},{"word":"Brazil","meaning":"Country: Brazil","burmese":""},{"word":"Brazilian","meaning":"Nationality: Brazilian","burmese":""},{"word":"Portuguese","meaning":"Language: Portuguese","burmese":""},{"word":"Bulgaria","meaning":"Country: Bulgaria","burmese":""},{"word":"Bulgarian","meaning":"Nationality and Language: Bulgarian","burmese":""},{"word":"Egypt","meaning":"Country: Egypt","burmese":""},{"word":"Egyptian","meaning":"Nationality: Egyptian","burmese":""},{"word":"Arabic","meaning":"Language: Arabic","burmese":""},{"word":"Japan","meaning":"Country: Japan","burmese":""},{"word":"Japanese","meaning":"Nationality and Language: Japanese","burmese":""},{"word":"Mexico","meaning":"Country: Mexico","burmese":""},{"word":"Mexican","meaning":"Nationality: Mexican","burmese":""},{"word":"Poland","meaning":"Country: Poland","burmese":""},{"word":"Polish","meaning":"Nationality and Language: Polish","burmese":""},{"word":"Russia","meaning":"Country: Russia","burmese":""},{"word":"Russian","meaning":"Nationality and Language: Russian","burmese":""},{"word":"Switzerland","meaning":"Country: Switzerland","burmese":""},{"word":"Swiss","meaning":"Nationality: Swiss","burmese":""},{"word":"Romansh","meaning":"Language spoken in Switzerland: Romansh","burmese":""},{"word":"Italian","meaning":"Language spoken in Switzerland: Italian","burmese":""},{"word":"French","meaning":"Language spoken in Switzerland: French","burmese":""},{"word":"Thailand","meaning":"Country: Thailand","burmese":""},{"word":"Thai","meaning":"Nationality and Language: Thai","burmese":""},{"word":"Turkey","meaning":"Country: Turkey","burmese":""},{"word":"Turkish","meaning":"Nationality and Language: Turkish","burmese":""}]}'::jsonb, 29) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049029-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-30', 'Fiction', 'This lesson covers different types of fictional books and literary genres.', '{"details":[{"word":"comic","meaning":"a book with pictures and speech bubbles telling a story","burmese":""},{"word":"crime novel","meaning":"a fiction book about a crime or investigation","burmese":""},{"word":"fairy tale","meaning":"a traditional story about magical creatures and events","burmese":""},{"word":"fantasy","meaning":"fiction featuring magical or supernatural elements","burmese":""},{"word":"graphic novel","meaning":"a long comic book story in book form","burmese":""},{"word":"historical fiction","meaning":"fiction set in a particular time period in the past","burmese":""},{"word":"horror","meaning":"fiction intended to frighten the reader","burmese":""},{"word":"play","meaning":"a piece of fiction written for performance on stage","burmese":""},{"word":"romance","meaning":"fiction about love and relationships","burmese":""},{"word":"science fiction","meaning":"fiction based on imagined scientific developments or space travel","burmese":""},{"word":"thriller","meaning":"fiction that is exciting and holds the reader''s interest","burmese":""}]}'::jsonb, 30) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00049030-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 49), 'unit49-lesson-31', 'Non-fiction', 'This lesson covers different types of non-fiction books and reading materials.', '{"details":[{"word":"atlas","meaning":"a book of maps","burmese":""},{"word":"autobiography","meaning":"a book about a person''s life written by that person","burmese":""},{"word":"biography","meaning":"a book about a person''s life written by someone else","burmese":""},{"word":"cookbook","meaning":"a book containing recipes and instructions for cooking","burmese":""},{"word":"encyclopaedia","meaning":"a book or set of books with information on many subjects","burmese":""},{"word":"guidebook","meaning":"a book with information about a place for visitors","burmese":""},{"word":"magazine","meaning":"a publication with articles and pictures, issued regularly","burmese":""},{"word":"manual","meaning":"a book of instructions, especially for operating equipment","burmese":""},{"word":"newspaper","meaning":"a publication with news, articles, and advertisements printed on paper","burmese":""},{"word":"textbook","meaning":"a book used as a standard work for the study of a subject","burmese":""}]}'::jsonb, 31) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex1', 'multiple_choice', 'Choose the correct answer for each question about school subjects and daily routines.', '[{"id":4901,"question":"Which subject studies living organisms?","options":["art","biology","geography"],"answer":"biology","explanation":"Biology is the study of living organisms and life processes.","explanation_burmese":"","points":1},{"id":4902,"question":"What do you do before leaving the house in the morning?","options":["have dinner","go to bed","get dressed"],"answer":"get dressed","explanation":"Getting dressed is part of the morning routine before leaving the house.","explanation_burmese":"","points":1},{"id":4903,"question":"Which subject involves learning about countries and maps?","options":["history","geography","physics"],"answer":"geography","explanation":"Geography is the study of countries, maps, and the physical features of the Earth.","explanation_burmese":"","points":1},{"id":4904,"question":"When do you have lunch?","options":["in the morning","in the middle of the day","at night"],"answer":"in the middle of the day","explanation":"Lunch is a meal eaten in the middle of the day.","explanation_burmese":"","points":1},{"id":4905,"question":"Which subject studies matter, energy, and forces?","options":["physics","Spanish","ICT"],"answer":"physics","explanation":"Physics is the study of matter, energy, motion, and forces.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049001-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex2', 'multiple_choice', 'Choose the correct free-time activity for each description.', '[{"id":4906,"question":"What do you do when you use a computer to explore websites?","options":["draw","surf the Internet","take photos"],"answer":"surf the Internet","explanation":"Surfing the Internet means browsing websites online.","explanation_burmese":"","points":1},{"id":4907,"question":"Which activity involves moving to music?","options":["read","chat online","dance"],"answer":"dance","explanation":"Dancing involves moving your body to the rhythm of music.","explanation_burmese":"","points":1},{"id":4908,"question":"What do you do when you go to a shop to buy things?","options":["go out with friends","go shopping","play the piano"],"answer":"go shopping","explanation":"Going shopping means visiting shops to buy items.","explanation_burmese":"","points":1},{"id":4909,"question":"Which activity uses a camera?","options":["listen to music","take photos","draw"],"answer":"take photos","explanation":"Taking photos means capturing images with a camera.","explanation_burmese":"","points":1},{"id":4910,"question":"What do you do when you use a musical instrument with strings and keys?","options":["play the guitar","do sport","surf the Internet"],"answer":"play the guitar","explanation":"Playing the guitar involves performing music on a guitar.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049002-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex3', 'multiple_choice', 'Choose the correct place to go in a town for each description.', '[{"id":4911,"question":"Where do you go to watch films on a big screen?","options":["library","cinema","museum"],"answer":"cinema","explanation":"A cinema is where you go to watch films on a big screen.","explanation_burmese":"","points":1},{"id":4912,"question":"Where can you borrow books to read?","options":["theatre","library","sports centre"],"answer":"library","explanation":"A library is a place where you can borrow and read books.","explanation_burmese":"","points":1},{"id":4913,"question":"Where do you go to swim in a pool?","options":["stadium","park","swimming pool"],"answer":"swimming pool","explanation":"A swimming pool is designed for swimming activities.","explanation_burmese":"","points":1},{"id":4914,"question":"Where can you eat a quick meal like burgers and chips?","options":["museum","fast-food restaurant","library"],"answer":"fast-food restaurant","explanation":"A fast-food restaurant serves quick meals like burgers and chips.","explanation_burmese":"","points":1},{"id":4915,"question":"Where do you go to see plays and performances?","options":["theatre","shopping centre","cinema"],"answer":"theatre","explanation":"A theatre is where live plays and performances are shown.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049003-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex4', 'multiple_choice', 'Choose the correct room in a house for each description.', '[{"id":4916,"question":"Which room do you sleep in?","options":["kitchen","bedroom","garage"],"answer":"bedroom","explanation":"A bedroom is the room where you sleep.","explanation_burmese":"","points":1},{"id":4917,"question":"Which room has a bath and shower?","options":["living room","dining room","bathroom"],"answer":"bathroom","explanation":"A bathroom contains a bath, shower, and toilet.","explanation_burmese":"","points":1},{"id":4918,"question":"Which room do you cook food in?","options":["kitchen","garden","hall"],"answer":"kitchen","explanation":"A kitchen is where you cook and prepare food.","explanation_burmese":"","points":1},{"id":4919,"question":"Where do you eat meals with your family?","options":["bathroom","dining room","garage"],"answer":"dining room","explanation":"A dining room is the room where family meals are eaten.","explanation_burmese":"","points":1},{"id":4920,"question":"Which room do you relax and watch TV in?","options":["kitchen","living room","bathroom"],"answer":"living room","explanation":"A living room is where you relax, watch TV, and spend time with family.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049004-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex5', 'multiple_choice', 'Choose the correct household object or furniture for each description.', '[{"id":4921,"question":"What do you sit on to eat at a table?","options":["sofa","chair","shelf"],"answer":"chair","explanation":"A chair is furniture you sit on, especially at a table.","explanation_burmese":"","points":1},{"id":4922,"question":"Which appliance keeps food cold and fresh?","options":["microwave","fridge","cooker"],"answer":"fridge","explanation":"A fridge keeps food cold and fresh to stop it from going bad.","explanation_burmese":"","points":1},{"id":4923,"question":"What do you watch programmes on?","options":["TV","lamp","mirror"],"answer":"TV","explanation":"A TV is used to watch programmes, films, and news.","explanation_burmese":"","points":1},{"id":4924,"question":"Which appliance cooks food quickly using radiation?","options":["dishwasher","microwave","washing machine"],"answer":"microwave","explanation":"A microwave cooks or heats food quickly using microwave radiation.","explanation_burmese":"","points":1},{"id":4925,"question":"What do you sleep on at night?","options":["armchair","bed","desk"],"answer":"bed","explanation":"A bed is where you sleep at night.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049005-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex6', 'multiple_choice', 'Choose the correct job around the house for each description.', '[{"id":4926,"question":"What do you do when you put clothes in a machine with water and soap?","options":["tidy up","do the washing","lay the table"],"answer":"do the washing","explanation":"Doing the washing means putting clothes in a washing machine.","explanation_burmese":"","points":1},{"id":4927,"question":"What do you do before eating a meal?","options":["take the rubbish out","lay the table","do the ironing"],"answer":"lay the table","explanation":"Laying the table means putting plates, knives, and forks on the table before a meal.","explanation_burmese":"","points":1},{"id":4928,"question":"What do you do with dirty plates after eating?","options":["make the bed","wash the dishes","do the shopping"],"answer":"wash the dishes","explanation":"Washing the dishes means cleaning plates and cutlery after a meal.","explanation_burmese":"","points":1},{"id":4929,"question":"What do you do when you make a room neat and orderly?","options":["do the ironing","tidy up","take the rubbish out"],"answer":"tidy up","explanation":"Tidying up means making a room or space neat and orderly.","explanation_burmese":"","points":1},{"id":4930,"question":"What do you do with a hot iron and clothes?","options":["do the ironing","do the washing","lay the table"],"answer":"do the ironing","explanation":"Doing the ironing means using a hot iron to remove wrinkles from clothes.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049006-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex7', 'multiple_choice', 'Choose the correct part of the body for each description.', '[{"id":4931,"question":"Which body part do you see with?","options":["ear","nose","eye"],"answer":"eye","explanation":"Eyes are the body parts used for seeing.","explanation_burmese":"","points":1},{"id":4932,"question":"Which body part is used for hearing?","options":["ear","mouth","shoulder"],"explanation":"Ears are used for hearing sounds.","answer":"ear","explanation_burmese":"","points":1},{"id":4933,"question":"Which body part bends in the middle of your leg?","options":["ankle","knee","wrist"],"answer":"knee","explanation":"The knee is the joint in the middle of your leg that bends.","explanation_burmese":"","points":1},{"id":4934,"question":"Which body part do you use to hold things?","options":["hand","foot","head"],"answer":"hand","explanation":"Hands are used to hold, touch, and grab things.","explanation_burmese":"","points":1},{"id":4935,"question":"Where is your stomach located?","options":["on your head","on your chest","in the middle of your body"],"answer":"in the middle of your body","explanation":"The stomach is located in the middle part of the body, below the chest.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049007-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex8', 'multiple_choice', 'Choose the correct physical activity for each description.', '[{"id":4936,"question":"What do you do when you move quickly on your feet?","options":["swim","run","ski"],"answer":"run","explanation":"Running means moving quickly on your feet.","explanation_burmese":"","points":1},{"id":4937,"question":"What do you do in water without sinking?","options":["jump","ride","swim"],"answer":"swim","explanation":"Swimming means moving through water without sinking.","explanation_burmese":"","points":1},{"id":4938,"question":"What do you do when you use your foot to hit a ball?","options":["kick","hit","climb"],"answer":"kick","explanation":"Kicking means hitting something with your foot.","explanation_burmese":"","points":1},{"id":4939,"question":"What do you do when you go up a mountain or wall?","options":["fall","climb","dive"],"answer":"climb","explanation":"Climbing means going up a mountain, wall, or other high structure.","explanation_burmese":"","points":1},{"id":4940,"question":"What do you do on ice with special boots?","options":["ski","skate","ride"],"answer":"skate","explanation":"Skating means moving on ice wearing special boots with blades.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049008-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex9', 'multiple_choice', 'Choose the correct sport for each description.', '[{"id":4941,"question":"Which sport uses a bat and ball on a diamond-shaped field?","options":["baseball","tennis","golf"],"answer":"baseball","explanation":"Baseball is played with a bat and ball on a diamond-shaped field.","explanation_burmese":"","points":1},{"id":4942,"question":"Which sport involves jumping on a horse?","options":["cycling","horse-riding","skiing"],"answer":"horse-riding","explanation":"Horse-riding involves riding and jumping on a horse.","explanation_burmese":"","points":1},{"id":4943,"question":"Which sport is played in a pool with cues and balls?","options":["volleyball","swimming","table tennis"],"answer":"table tennis","explanation":"Table tennis, also known as ping pong, is played on a table with paddles and a ball.","explanation_burmese":"","points":1},{"id":4944,"question":"Which sport involves moving through water in the sea?","options":["sailing","fishing","climbing"],"answer":"sailing","explanation":"Sailing involves traveling through water on a boat with sails.","explanation_burmese":"","points":1},{"id":4945,"question":"Which sport involves two people hitting a ball over a net?","options":["rugby","tennis","diving"],"answer":"tennis","explanation":"Tennis is played by two people (or pairs) hitting a ball over a net.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049009-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex10', 'multiple_choice', 'Choose the correct nationality for each country.', '[{"id":4946,"question":"Someone from Japan is called a...","options":["Chinese","Japanese","Korean"],"answer":"Japanese","explanation":"People from Japan are called Japanese.","explanation_burmese":"","points":1},{"id":4947,"question":"Someone from Brazil is called a...","options":["Argentinian","Mexican","Brazilian"],"answer":"Brazilian","explanation":"People from Brazil are called Brazilian.","explanation_burmese":"","points":1},{"id":4948,"question":"Someone from Poland is called a...","options":["Polish","Russian","Czech"],"answer":"Polish","explanation":"People from Poland are called Polish.","explanation_burmese":"","points":1},{"id":4949,"question":"Someone from Egypt is called a...","options":["Turkish","Egyptian","Peruvian"],"answer":"Egyptian","explanation":"People from Egypt are called Egyptian.","explanation_burmese":"","points":1},{"id":4950,"question":"Someone from Spain is called a...","options":["Spanish","Italian","Greek"],"answer":"Spanish","explanation":"People from Spain are called Spanish.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049010-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex11', 'multiple_choice', 'Choose the correct word connected with tourism for each description.', '[{"id":4951,"question":"What do you need to travel to another country?","options":["souvenir","passport","guidebook"],"answer":"passport","explanation":"A passport is an official document needed to travel to another country.","explanation_burmese":"","points":1},{"id":4952,"question":"What do you buy to enter a concert or museum?","options":["luggage","tickets","souvenir"],"answer":"tickets","explanation":"Tickets are bought to enter events, concerts, museums, and transport.","explanation_burmese":"","points":1},{"id":4953,"question":"What is a book that helps tourists find their way around?","options":["luggage","guidebook","package holiday"],"answer":"guidebook","explanation":"A guidebook is a book that gives tourists information about a place.","explanation_burmese":"","points":1},{"id":4954,"question":"What do you buy to remember a holiday?","options":["souvenir","tickets","passport"],"answer":"souvenir","explanation":"A souvenir is something you buy to remember a holiday or trip.","explanation_burmese":"","points":1},{"id":4955,"question":"What is a trip where flights, hotel, and food are all included?","options":["sightseeing","package holiday","excursion"],"answer":"package holiday","explanation":"A package holiday includes flights, hotel, and meals all together.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049011-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex12', 'multiple_choice', 'Choose the correct type of transport for each description.', '[{"id":4956,"question":"Which transport flies in the sky?","options":["bus","plane","boat"],"answer":"plane","explanation":"A plane is a vehicle that flies through the sky.","explanation_burmese":"","points":1},{"id":4957,"question":"Which transport travels on rails?","options":["car","coach","train"],"answer":"train","explanation":"A train travels on rails along a railway track.","explanation_burmese":"","points":1},{"id":4958,"question":"Which transport is the smallest and goes on two wheels?","options":["bus","moped","ship"],"answer":"moped","explanation":"A moped is a small motorized vehicle with two wheels.","explanation_burmese":"","points":1},{"id":4959,"question":"Which transport travels on water and is large?","options":["van","ship","lorry"],"answer":"ship","explanation":"A ship is a large vehicle that travels on water.","explanation_burmese":"","points":1},{"id":4960,"question":"Which transport has four wheels and carries passengers on the road?","options":["car","tram","bike"],"answer":"car","explanation":"A car is a four-wheeled vehicle used for road transport.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049012-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex13', 'multiple_choice', 'Choose the correct place of work for each description.', '[{"id":4961,"question":"Where do people who make things work?","options":["office","factory","studio"],"answer":"factory","explanation":"A factory is where products are made by workers.","explanation_burmese":"","points":1},{"id":4962,"question":"Where do people who treat sick people work?","options":["hospital","restaurant","clinic"],"answer":"hospital","explanation":"A hospital is where doctors and nurses treat sick people.","explanation_burmese":"","points":1},{"id":4963,"question":"Where do teachers and students go?","options":["shop","school","studio"],"answer":"school","explanation":"A school is where teachers teach and students learn.","explanation_burmese":"","points":1},{"id":4964,"question":"Where do people buy food and drink to eat?","options":["restaurant","factory","office"],"answer":"restaurant","explanation":"A restaurant is where people pay to eat meals prepared by a cook.","explanation_burmese":"","points":1},{"id":4965,"question":"Where do artists create paintings and sculptures?","options":["studio","clinic","garage"],"answer":"studio","explanation":"A studio is where artists create their work, such as paintings or music.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049013-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex14', 'multiple_choice', 'Choose the correct job for each description.', '[{"id":4966,"question":"Who looks after patients in a hospital?","options":["nurse","secretary","waiter"],"answer":"nurse","explanation":"A nurse looks after patients in a hospital.","explanation_burmese":"","points":1},{"id":4967,"question":"Who repairs cars?","options":["builder","mechanic","engineer"],"answer":"mechanic","explanation":"A mechanic repairs and maintains vehicles.","explanation_burmese":"","points":1},{"id":4968,"question":"Who teaches students in a school?","options":["doctor","teacher","farmer"],"answer":"teacher","explanation":"A teacher teaches students in a school.","explanation_burmese":"","points":1},{"id":4969,"question":"Who serves food and drink to customers in a restaurant?","options":["chef","waiter","journalist"],"answer":"waiter","explanation":"A waiter serves food and drink to customers in a restaurant.","explanation_burmese":"","points":1},{"id":4970,"question":"Who writes articles for newspapers?","options":["journalist","dentist","artist"],"answer":"journalist","explanation":"A journalist writes articles and reports for newspapers and media.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049014-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex15', 'multiple_choice', 'Choose the correct word connected with culture and work.', '[{"id":4971,"question":"Who writes plays for the theatre?","options":["poet","playwright","painter"],"answer":"playwright","explanation":"A playwright is a person who writes plays for the theatre.","explanation_burmese":"","points":1},{"id":4972,"question":"Who writes poems?","options":["novelist","poet","dancer"],"answer":"poet","explanation":"A poet is a person who writes poems.","explanation_burmese":"","points":1},{"id":4973,"question":"Who creates paintings and artworks?","options":["composer","director","painter"],"answer":"painter","explanation":"A painter is a person who creates paintings and artworks.","explanation_burmese":"","points":1},{"id":4974,"question":"Who writes novels and longer works of fiction?","options":["novelist","musician","singer"],"answer":"novelist","explanation":"A novelist is a person who writes novels.","explanation_burmese":"","points":1},{"id":4975,"question":"Who creates music and compositions?","options":["dancer","composer","actor"],"answer":"composer","explanation":"A composer is a person who creates and writes music.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049015-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex16', 'multiple_choice', 'Choose the correct container for each item.', '[{"id":4976,"question":"Water usually comes in a...","options":["packet","bottle","slice"],"answer":"bottle","explanation":"Water usually comes in a bottle of water.","explanation_burmese":"","points":1},{"id":4977,"question":"Biscuits usually come in a...","options":["can","carton","packet"],"answer":"packet","explanation":"Biscuits usually come in a packet of biscuits.","explanation_burmese":"","points":1},{"id":4978,"question":"Orange juice often comes in a...","options":["carton","slice","bottle"],"answer":"carton","explanation":"Orange juice often comes in a carton of orange juice.","explanation_burmese":"","points":1},{"id":4979,"question":"Fizzy drinks like cola come in a...","options":["glass","can","carton"],"answer":"can","explanation":"Fizzy drinks like cola come in a can of fizzy drink.","explanation_burmese":"","points":1},{"id":4980,"question":"Pizza is often served as a...","options":["slice","can","cup"],"answer":"slice","explanation":"A slice of pizza is a single piece cut from a whole pizza.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049016-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex17', 'multiple_choice', 'Choose the correct wild animal or insect for each description.', '[{"id":4981,"question":"Which animal has black and yellow stripes and makes honey?","options":["spider","bee","scorpion"],"answer":"bee","explanation":"A bee has black and yellow stripes and produces honey.","explanation_burmese":"","points":1},{"id":4982,"question":"Which animal is a large cat with orange and black stripes?","options":["wolf","tiger","bear"],"answer":"tiger","explanation":"A tiger is a large cat with distinctive orange and black stripes.","explanation_burmese":"","points":1},{"id":4983,"question":"Which creature has eight legs and spins webs?","options":["snake","lizard","spider"],"answer":"spider","explanation":"A spider has eight legs and is known for spinning webs.","explanation_burmese":"","points":1},{"id":4984,"question":"Which animal lives in water and has sharp teeth?","options":["shark","eagle","wolf"],"answer":"shark","explanation":"A shark lives in the sea and has sharp teeth.","explanation_burmese":"","points":1},{"id":4985,"question":"Which animal flies high in the sky and has sharp eyes?","options":["tiger","eagle","bear"],"answer":"eagle","explanation":"An eagle is a bird that flies high and has very sharp eyesight.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049017-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex18', 'multiple_choice', 'Choose the correct feature of the natural world for each description.', '[{"id":4986,"question":"A large body of fresh water surrounded by land is called a...","options":["river","lake","field"],"answer":"lake","explanation":"A lake is a large body of fresh water surrounded by land.","explanation_burmese":"","points":1},{"id":4987,"question":"What is a very tall natural elevation of the earth''s surface?","options":["valley","mountain","island"],"answer":"mountain","explanation":"A mountain is a very tall natural elevation of the earth''s surface.","explanation_burmese":"","points":1},{"id":4988,"question":"Where do you find trees growing together in a large area?","options":["forest","hill","sky"],"answer":"forest","explanation":"A forest is a large area covered with many trees.","explanation_burmese":"","points":1},{"id":4989,"question":"What is land completely surrounded by water called?","options":["valley","island","waterfall"],"answer":"island","explanation":"An island is land completely surrounded by water.","explanation_burmese":"","points":1},{"id":4990,"question":"What do you call water falling from a height in nature?","options":["river","waterfall","lake"],"answer":"waterfall","explanation":"A waterfall is water falling from a height in nature.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049018-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex19', 'multiple_choice', 'Choose the correct weather word for each description.', '[{"id":4991,"question":"When water falls from clouds, what is the weather?","options":["windy","rainy","sunny"],"answer":"rainy","explanation":"Rainy weather means water falls from clouds.","explanation_burmese":"","points":1},{"id":4992,"question":"When the sun is shining and the sky is clear, the weather is...","options":["sunny","cloudy","stormy"],"answer":"sunny","explanation":"Sunny weather means the sun is shining and the sky is clear.","explanation_burmese":"","points":1},{"id":4993,"question":"When it snows, the weather is called...","options":["foggy","snowy","dry"],"answer":"snowy","explanation":"Snowy weather means snow is falling from the sky.","explanation_burmese":"","points":1},{"id":4994,"question":"When strong winds blow and there is thunder, what is the weather?","options":["warm","stormy","hot"],"answer":"stormy","explanation":"Stormy weather includes strong winds, thunder, and lightning.","explanation_burmese":"","points":1},{"id":4995,"question":"When you cannot see far because of thick cloud near the ground, the weather is...","options":["dry","windy","foggy"],"answer":"foggy","explanation":"Foggy weather means thick cloud is near the ground and you cannot see far.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049019-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex20', 'multiple_choice', 'Choose the correct feeling for each description.', '[{"id":4996,"question":"When something unexpected happens, how might you feel?","options":["tired","surprised","bored"],"answer":"surprised","explanation":"Feeling surprised means something unexpected has happened.","explanation_burmese":"","points":1},{"id":4997,"question":"When you have nothing interesting to do, you feel...","options":["excited","bored","happy"],"answer":"bored","explanation":"Feeling bored means you have nothing interesting to do.","explanation_burmese":"","points":1},{"id":4998,"question":"When something bad happens and you feel unhappy, you are...","options":["disappointed","excited","relaxed"],"answer":"disappointed","explanation":"Feeling disappointed means you are unhappy because something did not go well.","explanation_burmese":"","points":1},{"id":4999,"question":"When you are calm and not worried, you feel...","options":["stressed","angry","relaxed"],"answer":"relaxed","explanation":"Feeling relaxed means you are calm and not worried.","explanation_burmese":"","points":1},{"id":5000,"question":"When you are afraid of something, you feel...","options":["frightened","interested","happy"],"answer":"frightened","explanation":"Feeling frightened means you are afraid of something.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049020-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex21', 'multiple_choice', 'Choose the correct personality trait for each description.', '[{"id":5001,"question":"Someone who always works hard is...","options":["lazy","hard-working","quiet"],"answer":"hard-working","explanation":"A hard-working person always puts effort into their work.","explanation_burmese":"","points":1},{"id":5002,"question":"Someone who is very clever and good at learning is...","options":["cheerful","lazy","intelligent"],"answer":"intelligent","explanation":"An intelligent person is very clever and good at learning.","explanation_burmese":"","points":1},{"id":5003,"question":"Someone who does not talk much is...","options":["serious","quiet","cheerful"],"answer":"quiet","explanation":"A quiet person does not talk much.","explanation_burmese":"","points":1},{"id":5004,"question":"Someone who is always happy and smiles a lot is...","options":["cheerful","serious","lazy"],"answer":"cheerful","explanation":"A cheerful person is always happy and smiles a lot.","explanation_burmese":"","points":1},{"id":5005,"question":"Someone who always does what they are supposed to do is...","options":["lazy","responsible","angry"],"answer":"responsible","explanation":"A responsible person always does what they are supposed to do.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049021-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex22', 'multiple_choice', 'Choose the correct social problem for each description.', '[{"id":5006,"question":"When people do not have enough food, the problem is...","options":["pollution","hunger","unemployment"],"answer":"hunger","explanation":"Hunger is the social problem when people do not have enough food.","explanation_burmese":"","points":1},{"id":5007,"question":"When people do not have jobs, the problem is...","options":["violence","homelessness","unemployment"],"answer":"unemployment","explanation":"Unemployment is the problem when people do not have jobs.","explanation_burmese":"","points":1},{"id":5008,"question":"When the air and water are dirty, the problem is...","options":["crime","poverty","pollution"],"answer":"pollution","explanation":"Pollution is the problem when the air, water, or land is dirty.","explanation_burmese":"","points":1},{"id":5009,"question":"When people do not have enough money to live, the problem is...","options":["poverty","crime","hunger"],"answer":"poverty","explanation":"Poverty is the social problem when people do not have enough money to live.","explanation_burmese":"","points":1},{"id":5010,"question":"When people hurt or harm others, the problem is...","options":["violence","pollution","homelessness"],"answer":"violence","explanation":"Violence is the social problem when people hurt or harm others.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049022-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex23', 'multiple_choice', 'Choose the correct item of clothing for each description.', '[{"id":5011,"question":"What do you wear on your legs and feet?","options":["jacket","trousers","shirt"],"answer":"trousers","explanation":"Trousers are worn on the legs and cover the lower body.","explanation_burmese":"","points":1},{"id":5012,"question":"What do women wear as a one-piece garment for the body?","options":["shorts","dress","jumper"],"answer":"dress","explanation":"A dress is a one-piece garment worn mainly by women.","explanation_burmese":"","points":1},{"id":5013,"question":"What do you wear over a shirt when it is cold?","options":["sweatshirt","belt","hat"],"answer":"sweatshirt","explanation":"A sweatshirt is worn over a shirt to keep warm.","explanation_burmese":"","points":1},{"id":5014,"question":"What do men wear around their neck with a suit?","options":["scarf","tie","jewellery"],"answer":"tie","explanation":"A tie is worn around the neck with a suit, usually by men.","explanation_burmese":"","points":1},{"id":5015,"question":"What is a warm outer garment worn in winter?","options":["jeans","coat","shorts"],"answer":"coat","explanation":"A coat is a warm outer garment worn in cold weather.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049023-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex24', 'multiple_choice', 'Choose the correct accessory for each description.', '[{"id":5016,"question":"What do you wear on your head to protect from the sun?","options":["belt","hat","watch"],"answer":"hat","explanation":"A hat is worn on the head for protection or fashion.","explanation_burmese":"","points":1},{"id":5017,"question":"What do you wear to protect your eyes from the sun?","options":["glasses","sunglasses","scarf"],"answer":"sunglasses","explanation":"Sunglasses protect your eyes from the sun''s bright light.","explanation_burmese":"","points":1},{"id":5018,"question":"What do you wear around your waist to hold up trousers?","options":["scarf","belt","jewellery"],"answer":"belt","explanation":"A belt is worn around the waist to hold up trousers.","explanation_burmese":"","points":1},{"id":5019,"question":"What do you wear around your neck to keep warm?","options":["watch","hat","scarf"],"answer":"scarf","explanation":"A scarf is worn around the neck to keep warm in cold weather.","explanation_burmese":"","points":1},{"id":5020,"question":"What do you look at to tell the time?","options":["glasses","belt","watch"],"answer":"watch","explanation":"A watch is worn on the wrist to tell the time.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049024-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex25', 'multiple_choice', 'Choose the correct type of shop for each description.', '[{"id":5021,"question":"Where do you buy bread and cakes?","options":["bakery","butcher''s","bank"],"answer":"bakery","explanation":"A bakery is where you buy bread, cakes, and other baked goods.","explanation_burmese":"","points":1},{"id":5022,"question":"Where do you buy meat?","options":["greengrocer''s","butcher''s","bakery"],"answer":"butcher''s","explanation":"A butcher''s shop is where you buy meat.","explanation_burmese":"","points":1},{"id":5023,"question":"Where do you buy vegetables and fruit?","options":["supermarket","greengrocer''s","chemist''s"],"answer":"greengrocer''s","explanation":"A greengrocer''s is where you buy vegetables and fruit.","explanation_burmese":"","points":1},{"id":5024,"question":"Where do you buy medicine?","options":["newsagent''s","chemist''s","stationery shop"],"answer":"chemist''s","explanation":"A chemist''s shop is where you buy medicine and health products.","explanation_burmese":"","points":1},{"id":5025,"question":"Where do you send and collect letters?","options":["bookshop","post office","department store"],"answer":"post office","explanation":"A post office is where you send and collect letters and packages.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049025-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex26', 'multiple_choice', 'Choose the correct age or stage of life for each description.', '[{"id":5026,"question":"A person who is 15 years old is called a...","options":["young adult","teenager","child"],"answer":"teenager","explanation":"A teenager is someone between 13 and 19 years old.","explanation_burmese":"","points":1},{"id":5027,"question":"A person who is 70 years old is called a...","options":["middle-aged","baby","senior citizen"],"answer":"senior citizen","explanation":"A senior citizen is someone who is 65 years old or older.","explanation_burmese":"","points":1},{"id":5028,"question":"A person who is 25 years old is called a...","options":["young adult","child","senior citizen"],"answer":"young adult","explanation":"A young adult is someone between 20 and 34 years old.","explanation_burmese":"","points":1},{"id":5029,"question":"A person who is 50 years old is called...","options":["middle-aged","teenager","young adult"],"answer":"middle-aged","explanation":"A middle-aged person is someone between 35 and 64 years old.","explanation_burmese":"","points":1},{"id":5030,"question":"A person who is 2 years old is called a...","options":["child","baby","teenager"],"answer":"baby","explanation":"A baby is a very young child, usually from birth to 3 years old.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049026-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex27', 'multiple_choice', 'Choose the correct family member for each description.', '[{"id":5031,"question":"Your mother''s mother is your...","options":["aunt","grandmother","niece"],"answer":"grandmother","explanation":"Your mother''s mother is your grandmother.","explanation_burmese":"","points":1},{"id":5032,"question":"Your father''s brother is your...","options":["nephew","cousin","uncle"],"answer":"uncle","explanation":"Your father''s brother is your uncle.","explanation_burmese":"","points":1},{"id":5033,"question":"Your sister''s son is your...","options":["grandson","nephew","niece"],"answer":"nephew","explanation":"Your sister''s son is your nephew.","explanation_burmese":"","points":1},{"id":5034,"question":"Your uncle''s daughter is your...","options":["niece","cousin","daughter"],"answer":"cousin","explanation":"Your uncle''s or aunt''s daughter is your cousin.","explanation_burmese":"","points":1},{"id":5035,"question":"A person you live with but are not married to is called your...","options":["wife","partner","brother"],"answer":"partner","explanation":"A partner is someone you live with but are not married to.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049027-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex28', 'multiple_choice', 'Choose the correct crime or criminal for each description.', '[{"id":5036,"question":"A person who breaks into houses to steal things is a...","options":["burglar","vandal","shoplifter"],"answer":"burglar","explanation":"A burglar breaks into houses or buildings to steal things.","explanation_burmese":"","points":1},{"id":5037,"question":"Taking things from a shop without paying is called...","options":["robbery","shoplifting","burglary"],"answer":"shoplifting","explanation":"Shoplifting is taking things from a shop without paying.","explanation_burmese":"","points":1},{"id":5038,"question":"A person who steals from shops is a...","options":["burglar","shoplifter","robber"],"answer":"shoplifter","explanation":"A shoplifter is a person who steals from shops.","explanation_burmese":"","points":1},{"id":5039,"question":"Breaking into a building to steal is called...","options":["vandalism","burglary","fraud"],"answer":"burglary","explanation":"Burglary is the crime of breaking into a building to steal.","explanation_burmese":"","points":1},{"id":5040,"question":"Damaging property on purpose is called...","options":["theft","vandalism","fraud"],"answer":"vandalism","explanation":"Vandalism is the crime of deliberately damaging property.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049028-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex29', 'multiple_choice', 'Choose the correct country, nationality, or language for each description.', '[{"id":5041,"question":"The official language of Japan is...","options":["Chinese","Korean","Japanese"],"answer":"Japanese","explanation":"The official language of Japan is Japanese.","explanation_burmese":"","points":1},{"id":5042,"question":"People from Switzerland are called...","options":["Austrian","Swiss","Dutch"],"answer":"Swiss","explanation":"People from Switzerland are called Swiss.","explanation_burmese":"","points":1},{"id":5043,"question":"The language spoken in Russia is...","options":["Polish","Russian","Ukrainian"],"answer":"Russian","explanation":"The language spoken in Russia is Russian.","explanation_burmese":"","points":1},{"id":5044,"question":"People from Austria are called...","options":["German","Austrian","Swiss"],"answer":"Austrian","explanation":"People from Austria are called Austrian.","explanation_burmese":"","points":1},{"id":5045,"question":"The official language of Egypt is...","options":["French","English","Arabic"],"answer":"Arabic","explanation":"The official language of Egypt is Arabic.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049029-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex30', 'multiple_choice', 'Choose the correct type of fiction for each description.', '[{"id":5046,"question":"A story with magic and imaginary worlds is called...","options":["horror","fantasy","thriller"],"answer":"fantasy","explanation":"Fantasy is a type of fiction with magic and imaginary worlds.","explanation_burmese":"","points":1},{"id":5047,"question":"A story intended to frighten people is called...","options":["romance","horror","fairy tale"],"answer":"horror","explanation":"Horror is a type of fiction intended to frighten readers.","explanation_burmese":"","points":1},{"id":5048,"question":"A story about a past time period is called...","options":["science fiction","historical fiction","comic"],"answer":"historical fiction","explanation":"Historical fiction is a story set in a past time period.","explanation_burmese":"","points":1},{"id":5049,"question":"A story set in the future with advanced technology is called...","options":["thriller","romance","science fiction"],"answer":"science fiction","explanation":"Science fiction is a story set in the future with advanced technology.","explanation_burmese":"","points":1},{"id":5050,"question":"A book with pictures and speech bubbles is called a...","options":["novel","comic","poem"],"answer":"comic","explanation":"A comic is a book with pictures and speech bubbles telling a story.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00049030-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 49), 'unit49-ex31', 'multiple_choice', 'Choose the correct type of non-fiction book for each description.', '[{"id":5051,"question":"A book with maps of the world is called an...","options":["encyclopaedia","atlas","manual"],"answer":"atlas","explanation":"An atlas is a book containing maps of the world.","explanation_burmese":"","points":1},{"id":5052,"question":"A book about someone''s life written by that person is called an...","options":["biography","autobiography","magazine"],"answer":"autobiography","explanation":"An autobiography is a book about someone''s life written by that person.","explanation_burmese":"","points":1},{"id":5053,"question":"A book about someone''s life written by another person is called a...","options":["biography","cookbook","textbook"],"answer":"biography","explanation":"A biography is a book about someone''s life written by another person.","explanation_burmese":"","points":1},{"id":5054,"question":"A book with recipes for cooking is called a...","options":["manual","cookbook","newspaper"],"answer":"cookbook","explanation":"A cookbook is a book containing recipes and cooking instructions.","explanation_burmese":"","points":1},{"id":5055,"question":"A book that teaches students about a subject is called a...","options":["textbook","magazine","atlas"],"answer":"textbook","explanation":"A textbook is a book used by students to learn about a subject.","explanation_burmese":"","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
